//! 生成表：档案表（`embedded.rs`）与片段表（`tables.rs`）的生成模板。

use std::fmt::Write as _;
use std::path::Path;

use crate::buildimage::{Outcome, outcome, recipe, require};
use crate::{Device, fail, variant};

// ── 档案表 ────────────────────────────────────────────────────────────

/// 直接生成强类型档案视图；运行期只读静态字段，不再构造通用表树。
pub fn archives_of(devices: &[Device]) -> String {
    let mut code = String::from(
        "// @generated by crates/prof/src/build.rs — do not edit.\n\
         // Source: crates/prof/src/<vendor>/<vendor>.toml, sorted by vendor.\n\
         /// 全部设备档案的强类型静态视图。\n\
         pub const PROFILE_VIEWS: &[crate::prof::ProfileView] = &[\n",
    );
    for device in devices {
        let _ = writeln!(code, "    {},", profile(device));
    }
    code.push_str(
        "];\n\n\
         /// 按名字取档案视图；名字不在表里时返回 `None`。\n\
         pub fn embedded(name: &str) -> Option<&'static crate::prof::ProfileView> {\n\
         \x20   PROFILE_VIEWS.iter().find(|profile| profile.vendor == name)\n\
         }\n\n\
         /// 档案名，按 vendor 升序。\n\
         pub fn names() -> &'static [&'static str] {\n\
         \x20   &[",
    );
    for device in devices {
        let _ = write!(code, "{:?},", device.name);
    }
    code.push_str("]\n}\n");
    code
}

/// 一台设备的完整静态字面量；所有必填字段都在构建期显式取值。
fn profile(device: &Device) -> String {
    let archive = archive_with_preamble(device);
    let meta = table(&archive, "meta");
    let compile = archive.get("compile").and_then(toml::Value::as_table);
    let flags = compile
        .and_then(|table| table.get("flags"))
        .map(values)
        .unwrap_or_default();
    let preamble = compile
        .and_then(|table| table.get("preamble"))
        .and_then(toml::Value::as_str)
        .unwrap_or("");
    format!(
        "crate::prof::ProfileView {{ vendor:{}, id:{}, tools:{}, tool_ver:{}, checked:{}, \
         emit:crate::prof::Emit::{}, fingerprint:{}, spaces:{}, mem:{}, simt:{}, units:{}, \
         provides:{}, flops_f32:{}, bw:{}, flags:{}, preamble:{:?}, headers:{} }}",
        required(meta, "vendor"),
        required(meta, "id"),
        required(meta, "tools"),
        optional(meta, "tool_ver"),
        optional(meta, "checked"),
        variant(required_text(meta, "emit")),
        fingerprints(&archive),
        spaces(&archive),
        memory(&archive),
        simt(&archive),
        units(&archive),
        provides(&archive),
        constant(&archive, "flops_f32"),
        constant(&archive, "bw"),
        strings(&flags),
        preamble,
        headers(compile),
    )
}

/// 必填表段。
fn table<'a>(value: &'a toml::Table, key: &str) -> &'a toml::Table {
    value
        .get(key)
        .and_then(toml::Value::as_table)
        .unwrap_or_else(|| fail(format!("档案缺 `{key}` 表")))
}

/// 必填字符串的 Rust 字面量。
fn required(table: &toml::Table, key: &str) -> String {
    format!("{:?}", required_text(table, key))
}

/// 必填字符串原文。
fn required_text<'a>(table: &'a toml::Table, key: &str) -> &'a str {
    table
        .get(key)
        .and_then(toml::Value::as_str)
        .unwrap_or_else(|| fail(format!("档案缺字符串 `{key}`")))
}

/// 可选字符串的既有缺省值 `-`。
fn optional(table: &toml::Table, key: &str) -> String {
    format!(
        "{:?}",
        table.get(key).and_then(toml::Value::as_str).unwrap_or("-")
    )
}

/// 标量或数组统一展开为文本序列。
fn values(value: &toml::Value) -> Vec<String> {
    match value {
        toml::Value::Array(items) => items.iter().map(scalar).collect(),
        scalar_value => vec![scalar(scalar_value)],
    }
}

/// 标量转文本；日期时间与嵌套表不是能力标量。
fn scalar(value: &toml::Value) -> String {
    match value {
        toml::Value::String(text) => text.clone(),
        toml::Value::Integer(number) => number.to_string(),
        toml::Value::Float(number) => number.to_string(),
        toml::Value::Boolean(flag) => flag.to_string(),
        other => fail(format!("不支持的能力标量 `{other:?}`")),
    }
}

/// 静态字符串切片字面量。
fn strings(values: &[String]) -> String {
    format!("&{values:?}")
}

/// `[fingerprint]` 的直接键或 `match` 子表。
fn fingerprints(archive: &toml::Table) -> String {
    let section = table(archive, "fingerprint");
    let rules = section
        .get("match")
        .and_then(toml::Value::as_table)
        .unwrap_or(section);
    let pairs: Vec<String> = rules
        .iter()
        .map(|(key, value)| format!("({key:?}, {:?})", required_value(value)))
        .collect();
    expressions(&pairs)
}

/// 规则必须是字符串，不把数值静默写成指纹。
fn required_value(value: &toml::Value) -> &str {
    value
        .as_str()
        .unwrap_or_else(|| fail("指纹规则只接受字符串"))
}

/// 三级存储名直接映射到现有闭集。
fn spaces(archive: &toml::Table) -> String {
    let pairs: Vec<String> = table(archive, "space")
        .iter()
        .map(|(key, value)| {
            format!(
                "(crate::atom::Space::{}, {:?})",
                variant(key),
                required_value(value)
            )
        })
        .collect();
    expressions(&pairs)
}

/// 整数缺省值同时是旧口径的下限。
fn integer(table: Option<&toml::Table>, key: &str, default: i64) -> i64 {
    table
        .and_then(|table| table.get(key))
        .and_then(toml::Value::as_integer)
        .unwrap_or(default)
        .max(default)
}

/// 数值型内存段不需要额外的视图类型。
fn memory(archive: &toml::Table) -> String {
    let mem = archive.get("mem").and_then(toml::Value::as_table);
    let fast = mem
        .and_then(|table| table.get("FAST"))
        .and_then(toml::Value::as_table);
    let reg = mem
        .and_then(|table| table.get("REG"))
        .and_then(toml::Value::as_table);
    format!(
        "crate::prof::Mem {{ fast_bytes:{}u64, fast_bank:{}u32, reg_bytes:{}u64 }}",
        integer(fast, "bytes", 0),
        integer(fast, "bank", 0),
        integer(reg, "bytes", 0),
    )
}

/// SIMT 段保留 `declared`，缺段不会被误写成已声明。
fn simt(archive: &toml::Table) -> String {
    let simt = archive.get("simt").and_then(toml::Value::as_table);
    format!(
        "crate::prof::Simt {{ group:{}u32, groups_max:{}u32, declared:{} }}",
        integer(simt, "group", 1),
        integer(simt, "groups_max", 1),
        simt.is_some()
    )
}

/// 执行单元：名字与静态存储切片。
fn units(archive: &toml::Table) -> String {
    let Some(units) = archive.get("units").and_then(toml::Value::as_table) else {
        return "&[]".to_string();
    };
    let entries: Vec<String> = units
        .iter()
        .map(|(name, value)| {
            let values = value
                .as_table()
                .and_then(|table| table.get("space"))
                .map(values)
                .unwrap_or_default()
                .iter()
                .map(|name| format!("crate::atom::Space::{}", variant(name)))
                .collect::<Vec<_>>();
            format!("({name:?}, {})", expressions(&values))
        })
        .collect();
    expressions(&entries)
}

/// 全部能力供给。
fn provides(archive: &toml::Table) -> String {
    let provides = archive
        .get("provides")
        .and_then(toml::Value::as_array)
        .unwrap_or_else(|| fail("档案缺 `provides` 数组"));
    let entries: Vec<String> = provides.iter().map(provide).collect();
    expressions(&entries)
}

/// 一条供给：签名段、证据等级、见证与属性全部保留。
fn provide(value: &toml::Value) -> String {
    let entry = value.as_table().unwrap_or_else(|| fail("供给只能是表"));
    let prim = required_text(entry, "prim");
    let imp = entry
        .get("impl")
        .and_then(toml::Value::as_str)
        .unwrap_or("-");
    let grade = required_text(entry, "grade");
    let extent = span(entry, &["m", "bytes", "extent"]);
    format!(
        "crate::prof::ProvideView {{ prim:crate::atom::Prim::{}, imp:{:?}, extent:{}, n:{}, k:{}, \
         dt:{}, space:{}, grade:crate::atom::Grade::{}, witness:{}, attrs:{} }}",
        variant(prim),
        imp,
        extent,
        span(entry, &["n"]),
        span(entry, &["k"]),
        closed_values(entry, "dt", "DType"),
        closed_values(entry, "space", "Space"),
        variant(grade),
        witness(entry),
        attrs(entry),
    )
}

/// 同一组同义区间只取已声明的一个；重复声明仍由构建校验拒绝。
fn span(entry: &toml::Table, aliases: &[&str]) -> String {
    aliases
        .iter()
        .find_map(|key| entry.get(*key))
        .map(|value| format!("Some({:?})", required_value(value)))
        .unwrap_or_else(|| "None".to_string())
}

/// 表达式切片不加字符串引号；用于闭集、见证数值与属性对象。
fn expressions(values: &[String]) -> String {
    format!("&[{}]", values.join(","))
}

/// 一组闭集名 → 静态元素切片。
fn closed_values(entry: &toml::Table, key: &str, kind: &str) -> String {
    let values = entry
        .get(key)
        .map(values)
        .unwrap_or_default()
        .iter()
        .map(|name| format!("crate::atom::{kind}::{}", variant(name)))
        .collect::<Vec<_>>();
    expressions(&values)
}

/// 见证：`(文件, 入口, f32 期望切片)`。
fn witness(entry: &toml::Table) -> String {
    let Some(table) = entry.get("witness").and_then(toml::Value::as_table) else {
        return "None".to_string();
    };
    let file = required(table, "file");
    let func = required(table, "func");
    let expect = table
        .get("expect")
        .and_then(toml::Value::as_array)
        .unwrap_or_else(|| fail("见证缺 `expect` 数组"))
        .iter()
        .map(|value| number(value, "f32"))
        .collect::<Vec<_>>();
    format!("Some(({file}, {func}, {}))", expressions(&expect))
}

/// 数值保持目标字面量类型。
fn number(value: &toml::Value, suffix: &str) -> String {
    if let Some(value) = value.as_integer() {
        return format!("{value}{suffix}");
    }
    if let Some(value) = value.as_float() {
        if !value.is_finite() {
            fail("声明语料的浮点数值必须有限，不接受 NaN / inf");
        }
        return format!("{value:?}{suffix}");
    }
    fail(format!("`{value:?}` 不是数值"))
}

/// 专属字段之外的键仍是属性，键和取值都不丢失。
fn attrs(entry: &toml::Table) -> String {
    let attrs: Vec<String> = entry
        .iter()
        .filter(|(key, _)| !parsed_key(key))
        .map(|(key, value)| {
            format!(
                "crate::decl::AttrView {{ key:crate::atom::AttrKey::{}, values:{} }}",
                variant(key),
                strings(&values(value))
            )
        })
        .collect();
    expressions(&attrs)
}

/// 供给表内已经有专属通道的键。
fn parsed_key(key: &str) -> bool {
    matches!(
        key,
        "prim"
            | "impl"
            | "m"
            | "bytes"
            | "extent"
            | "n"
            | "k"
            | "dt"
            | "space"
            | "grade"
            | "witness"
    )
}

/// 峰值 `(数值, 推导式)`；缺省为 `None`。
fn constant(archive: &toml::Table, key: &str) -> String {
    let Some(table) = archive
        .get("peak")
        .and_then(toml::Value::as_table)
        .and_then(|peak| peak.get(key))
        .and_then(toml::Value::as_table)
    else {
        return "None".to_string();
    };
    let value = number(
        table.get("value").unwrap_or_else(|| fail("峰值缺 `value`")),
        "f64",
    );
    format!("Some(({}, {}))", value, required(table, "src"))
}

/// 编译期头文件垫片 `(文件名, 内容)`。
fn headers(compile: Option<&toml::Table>) -> String {
    let Some(headers) = compile
        .and_then(|compile| compile.get("headers"))
        .and_then(toml::Value::as_table)
    else {
        return "&[]".to_string();
    };
    let values: Vec<String> = headers
        .iter()
        .map(|(name, value)| format!("({name:?}, {:?})", required_value(value)))
        .collect();
    expressions(&values)
}

/// 外置 `preamble.<ext>` 覆盖档案内联文本；没有外置文件时保持原档案不变。
fn archive_with_preamble(device: &Device) -> toml::Table {
    let mut archive = device.archive.clone();
    let Some(path) = &device.preamble else {
        return archive;
    };
    let source = std::fs::read_to_string(path)
        .unwrap_or_else(|error| fail(format!("读取 {} 失败：{error}", path.display())));
    let compile = archive
        .get_mut("compile")
        .and_then(toml::Value::as_table_mut)
        .unwrap_or_else(|| fail(format!("`{}` 的档案缺少 `[compile]` 表", device.name)));
    compile.insert("preamble".to_string(), toml::Value::String(source));
    archive
}

// ── 片段表 ────────────────────────────────────────────────────────────

/// 每台设备一个模块：片段、入口、尾块、源码根与设备行；末尾再合成四张聚合表。
pub fn tables_of(devices: &[Device], out: &Path, images: bool) -> String {
    let mut text = String::from(
        "// 由 `crates/prof/build.rs` 生成，不要手改。\n\
         //\n\
         // 每台设备一个模块：片段、入口、设备行与源码根；本文件末尾再把它们合成 `BUILTIN` /\n\
         // `WITNESS` / `DEVICES` / `ROOTS`。类型定义在 `src/`，所以生成代码不改变所有权表。\n",
    );
    for device in devices {
        // 镜像结局只算一次：生成的表与 `CUTILE_REQUIRE_IMAGE` 门禁读的是同一次编译的结果。
        let outcome = outcome(device, out, images);
        let _ = writeln!(
            text,
            "\n/// `{}` 设备的片段：原语 → 文本、原语 → 见证入口、设备行与源码根。\npub mod {} {{\n\
             #[allow(unused_imports)]\n\
             use crate::atom::Prim;\n\n\
             /// 本设备片段与见证所在目录，`device` 按它读磁盘。\n\
             pub const ROOT: &str = concat!(env!(\"CARGO_MANIFEST_DIR\"), \"/src/{}\");",
            device.name, device.name, device.family
        );
        fragments(&mut text, device);
        let _ = writeln!(
            text,
            "/// 写回尾块片段：`/* epi: <form> */` 分成六段，装配按段取用。\n\
             pub const EPILOGUE: &str = include_str!({:?});\n",
            device.epilogue.display().to_string()
        );
        prims(&mut text, device);
        device_line(&mut text, device, &outcome);
        text.push_str("}\n");
        require(device, &outcome);
    }
    aggregates(&mut text, devices);
    text
}

/// 片段表：`(原语, 文本)`，按原语名升序。
fn fragments(text: &mut String, device: &Device) {
    let _ = writeln!(
        text,
        "/// 片段：原语 → 文本，按原语名升序。\npub const FRAGMENTS: [(Prim, &str); {}] = [",
        device.fragments.len()
    );
    for (prim, path) in &device.fragments {
        let _ = writeln!(
            text,
            "    (Prim::{}, include_str!({:?})),",
            variant(prim),
            path.display().to_string()
        );
    }
    text.push_str("];\n");
}

/// 入口表：原语 → 见证里的入口名，顺序同 [`fragments`]。
fn prims(text: &mut String, device: &Device) {
    let _ = writeln!(
        text,
        "/// 原语 → 见证里的入口名：镜像里查的就是这个名字。\n\
         pub const PRIMS: [(Prim, &str); {}] = [",
        device.entries.len()
    );
    for (prim, entry) in &device.entries {
        let _ = writeln!(text, "    (Prim::{}, {entry:?}),", variant(prim));
    }
    text.push_str("];\n");
}

/// 设备行：入口表 + 档案元数据 + 见证源码 +（可选的）镜像 + 结局。
fn device_line(text: &mut String, device: &Device, outcome: &Outcome) {
    let _ = writeln!(
        text,
        "/// 设备行：本文件末尾把它连同另外几台设备合成 `DEVICES`。\n\
         pub const DEVICE: crate::Device = crate::Device {{\n\
         \x20   vendor: {:?},\n\
         \x20   ext: {:?},\n\
         \x20   emit: {:?},\n\
         \x20   tool: {:?},\n\
         \x20   tool_ver: {:?},\n\
         \x20   prims: &PRIMS,\n\
         \x20   epilogue: EPILOGUE,\n\
         \x20   source: include_str!({:?}),",
        device.name,
        device.ext,
        device.emit,
        device.tool,
        device.tool_ver,
        device.witness.display().to_string()
    );
    match outcome {
        Outcome::Compiled { path, symbols } => {
            let format = recipe(&device.emit).map_or("", |recipe| recipe.format);
            let _ = writeln!(
                text,
                "    image: Some(crate::Image::new({format:?}, include_bytes!({:?}), {symbols})),\n\
                 \x20   status: crate::Status::Compiled,",
                path.display().to_string()
            );
        }
        Outcome::Source => text.push_str("    image: None,\n    status: crate::Status::Source,\n"),
        Outcome::NoRecipe => {
            text.push_str("    image: None,\n    status: crate::Status::NoRecipe,\n")
        }
        Outcome::Skipped(reason) => {
            let _ = writeln!(
                text,
                "    image: None,\n    status: crate::Status::Skipped {{ reason: {reason:?} }},"
            );
        }
    }
    text.push_str("};\n");
}

/// 四张聚合表：`device` 拿它们回答"有哪些设备"与"这台设备的片段是什么"。
///
/// 长度由生成的模块数决定，不写死台数：加一份 `<vendor>.toml` 就多一台设备。
fn aggregates(text: &mut String, devices: &[Device]) {
    let count = devices.len();
    let names: Vec<&str> = devices.iter().map(|device| device.name.as_str()).collect();

    let _ = writeln!(
        text,
        "\n/// 每台设备的内嵌片段：`(vendor, ext, 片段)`。\npub const BUILTIN: [crate::Builtin; {count}] = ["
    );
    for name in &names {
        let _ = writeln!(
            text,
            "    crate::Builtin {{ vendor: {name}::DEVICE.vendor, ext: {name}::DEVICE.ext, \
             fragments: &{name}::FRAGMENTS }},"
        );
    }
    text.push_str("];\n");

    let _ = writeln!(
        text,
        "\n/// 内嵌的见证源码：`(vendor, ext, 文本)`。\npub const WITNESS: [(&str, &str, &str); {count}] = ["
    );
    for name in &names {
        let _ = writeln!(
            text,
            "    ({name}::DEVICE.vendor, {name}::DEVICE.ext, {name}::DEVICE.source),"
        );
    }
    text.push_str("];\n");

    let _ = writeln!(
        text,
        "\n/// 每台设备一行：vendor、输出语言、工具链、入口表、见证源码与（可选的）设备镜像。\n\
         pub static DEVICES: [crate::Device; {count}] = ["
    );
    for name in &names {
        let _ = writeln!(text, "    {name}::DEVICE,");
    }
    text.push_str("];\n");

    let _ = writeln!(
        text,
        "\n/// 每台设备的源码根目录：`(vendor, 目录)`。\npub const ROOTS: [(&str, &str); {count}] = ["
    );
    for name in &names {
        let _ = writeln!(text, "    ({name}::DEVICE.vendor, {name}::ROOT),");
    }
    text.push_str("];\n");
}
